def normalized(x):
    x = x - x.mean(0)
    return x / np.maximum(x.std(0), 1e-08)

def linear(x):
    f = normalized(x)
    return f @ f.T / f.shape[1]

def radial(x, l):
    f = normalized(x)
    d = np.maximum(0, np.diag(f @ f.T)[:, None] + np.diag(f @ f.T)[None, :] - 2 * f @ f.T)
    r = np.sqrt(5 * d / f.shape[1]) / l
    return (1 + r + r * r / 3) * np.exp(-r)

def features(d, z, w, kind):
    from sklearn.preprocessing import PolynomialFeatures
    from itertools import combinations
    blocks = []
    labels = []

    def add(n, f):
        if f.ndim == 1:
            f = f[:, None]
        blocks.append(f)
        labels.extend([n + ':' + str(j) for j in range(f.shape[1])])
    add('base', d)
    add('C1', z)
    add('C2', w)
    add('quadratic', PolynomialFeatures(2, include_bias=False).fit_transform(d)[:, 4:])
    add('cubic', PolynomialFeatures(3, include_bias=False).fit_transform(d)[:, 14:])
    for (n, f) in [('d', d), ('C1', z), ('C2', w), ('sum', z + w), ('diff', z - w), ('dc1', d + z), ('dc2', d + w), ('xprod', z * w)]:
        if kind and n in ('d', 'C1', 'C2'):
            f = np.column_stack([f] + [f[:, i] + sg * f[:, j] for (i, j) in combinations(range(4), 2) for sg in [-1, 1]])
        for k in [0.5, 1, 1.7, 2.5]:
            for (tag, v) in [('sin', np.sin(k * f)), ('cos', np.cos(k * f) - 1), ('tanh', np.tanh(k * f)), ('soft', f / (1 + k * abs(f))), ('rat', f / (1 + k * f * f)), ('evenrat', f * f / (1 + k * f * f))]:
                add(n + tag + str(k), v)
        for power in [2, 3]:
            add(n + '**' + str(power), f ** power)
        add(n + 'abs', abs(f))
        if n not in ('sum', 'diff', 'dc1', 'dc2', 'xprod'):
            add(n + 'cross', np.column_stack([f[:, i] * f[:, j] for (i, j) in combinations(range(f.shape[1]), 2)]))
    for (n, a, b) in [('z*w', z, w), ('z*d', z, d), ('w*d', w, d)]:
        add(n, (a[:, :, None] * b[:, None, :]).reshape(len(d), -1))
    return (np.column_stack(blocks), labels)
